// src/core/CalendarViewController.ts
var CalendarViewController = class {
  // 上次请求时间
  constructor(plugin) {
    this.plugin = plugin;
    this.requestCounter = 0;
    this.lastRequestTime = 0;
  }
  getShouldDisplayLunarInfo() {
    return this.plugin.database.setting.shouldDisplayLunarInfo;
  }
  setShouldDisplayLunarInfo(shouldDisplayLunarInfo) {
    this.plugin.database.setting.shouldDisplayLunarInfo = shouldDisplayLunarInfo;
  }
  getShouldDisplayHolidayInfo() {
    return this.plugin.database.setting.shouldDisplayHolidayInfo;
  }
  setShouldDisplayHolidayInfo(shouldDisplayHolidayInfo) {
    return this.plugin.database.setting.shouldDisplayHolidayInfo = shouldDisplayHolidayInfo;
  }
  // 立即刷新
  forceFlush() {
    const { workspace } = this.plugin.app;
    let leaf = null;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_CALENDAR);
    if (leaves.length > 0) {
      leaf = leaves[0];
      leaf.view.flush();
    }
  }
  /**
   * 请求刷新
   * 如果某个地方调用了请求刷新函数，就表示它需要刷新日历界面，但处于性能考虑，并不需要立即刷新
   * 默认情况下，该函数会在调用1秒之后刷新界面，在此期间，如果该函数再次被调用，那么刷新时间会继续向后顺延1秒
   */
  requestFlush() {
    this.requestCounter = this.requestCounter + 1;
    this.lastRequestTime = performance.now();
    setTimeout(() => {
      if (this.requestCounter <= 0) {
        return;
      }
      const now2 = performance.now();
      if (now2 - this.lastRequestTime < 990) {
        return;
      }
      this.requestCounter = 0;
      this.forceFlush();
    }, 1e3);
  }
};

// src/main.ts
var DustCalendarPlugin = class _DustCalendarPlugin extends import_obsidian6.Plugin {
  constructor(app, manifest) {
    super(app, manifest);
    this.database = new Database(this);
    this.noteController = new NoteController(this);
    this.templateController = new TemplateController(this);
    this.noteStatisticController = new NoteStatisticController(this);
    this.calendarViewController = new CalendarViewController(this);
    this.viewController = new ViewController(this);
    this.mainSettingTab = new MainSettingTab(this);
  }
  // 插件开启时执行初始化操作
  async onload() {
    await this.database.loadSetting();
    this.templateController.updateTemplatePlugin(this.database.setting.templatePlugin);
    this.viewController.setQuarterNameMode(this.database.setting.quarterNameMode);
    this.registerView(VIEW_TYPE_CALENDAR, (leaf) => new CalendarView(leaf, this));
    this.addCommand({
      id: "active-calendar-view",
      name: "\u6253\u5F00\u65E5\u5386\u89C6\u56FE",
      callback: () => {
        _DustCalendarPlugin.activateCalendarView(this);
      }
    });
    this.addCommand({
      id: "open-daily-note",
      name: "\u6253\u5F00/\u521B\u5EFA\u6BCF\u65E5\u7B14\u8BB0",
      callback: () => {
        const now2 = DateTime.now();
        this.noteController.openNoteByNoteType(DateTime.local(now2.year, now2.month, now2.day), 1 /* DAILY */);
      }
    });
    this.addCommand({
      id: "open-weekly-note",
      name: "\u6253\u5F00/\u521B\u5EFA\u6BCF\u5468\u7B14\u8BB0",
      callback: () => {
        const now2 = DateTime.now();
        const monday = now2.minus({ day: now2.weekday - 1 });
        this.noteController.openNoteByNoteType(DateTime.local(monday.year, monday.month, monday.day), 2 /* WEEKLY */);
      }
    });
    this.addCommand({
      id: "open-monthly-note",
      name: "\u6253\u5F00/\u521B\u5EFA\u6BCF\u6708\u7B14\u8BB0",
      callback: () => {
        const now2 = DateTime.now();
        this.noteController.openNoteByNoteType(DateTime.local(now2.year, now2.month), 3 /* MONTHLY */);
      }
    });
    this.addCommand({
      id: "open-quarterly-note",
      name: "\u6253\u5F00/\u521B\u5EFA\u5B63\u5EA6\u7B14\u8BB0",
      callback: () => {
        const now2 = DateTime.now();
        this.noteController.openNoteByNoteType(DateTime.local(now2.year, now2.quarter * 3 - 2), 4 /* QUARTERLY */);
      }
    });
    this.addCommand({
      id: "open-yearly-note",
      name: "\u6253\u5F00/\u521B\u5EFA\u5E74\u5EA6\u7B14\u8BB0",
      callback: () => {
        const now2 = DateTime.now();
        this.noteController.openNoteByNoteType(DateTime.local(now2.year), 5 /* YEARLY */);
      }
    });
    this.addSettingTab(this.mainSettingTab);
    if (this.app.workspace.layoutReady) {
      await _DustCalendarPlugin.activateCalendarView(this);
    }
  }
  // 关闭插件的时候执行释放资源的操作
  onunload() {
    this.database.saveSetting();
    this.app.workspace.getLeavesOfType(VIEW_TYPE_CALENDAR).forEach((leaf) => leaf.detach());
  }
  static async activateCalendarView(plugin) {
    const { workspace } = plugin.app;
    let leaf = null;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_CALENDAR);
    if (leaves.length > 0) {
      leaf = leaves[0];
    } else {
      leaf = workspace.getRightLeaf(false);
      if (leaf) {
        await leaf.setViewState({ type: VIEW_TYPE_CALENDAR, active: true });
      } else {
        throw new Error("\u65E0\u6CD5\u83B7\u53D6\u53F3\u4FA7\u89C6\u56FE\u53F6\u5B50");
      }
    }
    workspace.revealLeaf(leaf);
  }
};
